import { StyleSheet } from "@/lib/pdf-primitives";
import type { PdfcnTheme } from "@/types/pdf-themes";

/**
 * Creates all stats styles derived from the active theme.
 * @param t - The resolved PdfcnTheme instance.
 */
export const createStatsStyles = (t: PdfcnTheme) => {
  const { borderRadius, spacing, fontWeights, lineHeights, typography } =
    t.primitives;
  const valueBase = {
    color: t.colors.foreground,
    fontFamily: t.typography.heading.fontFamily,
    fontWeight: fontWeights.semibold,
    lineHeight: lineHeights.tight,
    // Lets long values without spaces break inside the tile instead of
    // pushing past its edge.
    overflowWrap: "anywhere",
  };

  return StyleSheet.create({
    container: {
      display: "flex",
      flexDirection: "column",
      marginBottom: t.spacing.componentGap,
      width: "100%",
    },
    label: {
      color: t.colors.mutedForeground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: 8,
      fontWeight: fontWeights.semibold,
      letterSpacing: 0.8,
      lineHeight: lineHeights.tight,
      marginBottom: spacing[1],
      overflowWrap: "anywhere",
      textTransform: "uppercase",
    },
    note: {
      fontFamily: t.typography.body.fontFamily,
      fontSize: 9,
      lineHeight: lineHeights.normal,
      marginTop: spacing[1],
      overflowWrap: "anywhere",
    },
    row: {
      flexDirection: "row",
      gap: spacing[2],
    },
    rowGap: {
      marginBottom: spacing[2],
    },
    spacer: {
      // Keeps a short last row aligned to the same tile width as full rows.
      flexBasis: 0,
      flexGrow: 1,
      minWidth: 0,
    },
    tile: {
      backgroundColor: t.colors.muted,
      borderRadius: borderRadius.md,
      // A zero basis splits the row evenly regardless of content length, and
      // minWidth: 0 keeps long unbroken values from widening their tile much.
      flexBasis: 0,
      flexGrow: 1,
      minWidth: 0,
      padding: spacing[3],
    },
    valueLg: { ...valueBase, fontSize: typography.xl },
    valueMd: { ...valueBase, fontSize: typography.lg },
    valueSm: { ...valueBase, fontSize: typography.base },
  });
};

import {
  usePdfcnTheme,
  useSafeMemo,
} from "@/components/pdf/theme-provider";
import {
  View,
  Text as PDFText,
} from "@/lib/pdf-primitives";
import type { Style } from "@/lib/pdf-primitives";
import { resolveColor } from "@/lib/resolve-color";

import { createStatsStyles } from "./stats.styles";
import type { StatItem, StatsColumns, StatsProps } from "./stats.types";

type Styles = ReturnType<typeof createStatsStyles>;

const getValueStyle = (columns: StatsColumns, styles: Styles): Style => {
  if (columns === 2) {
    return styles.valueLg;
  }
  if (columns === 4) {
    return styles.valueSm;
  }
  return styles.valueMd;
};

const chunkItems = (items: StatItem[], size: number): StatItem[][] => {
  const rows: StatItem[][] = [];
  for (let index = 0; index < items.length; index += size) {
    rows.push(items.slice(index, index + size));
  }
  return rows;
};

export const Stats = ({
  items,
  columns = 3,
  accentColor = "primary",
  noWrap = false,
  style,
}: StatsProps) => {
  const theme = usePdfcnTheme();
  const styles = useSafeMemo(() => createStatsStyles(theme), [theme]);

  if (items.length === 0) {
    return null;
  }

  const rows = chunkItems(items, columns);
  const valueStyle = getValueStyle(columns, styles);
  const noteStyle: Style[] = [
    styles.note,
    { color: resolveColor(accentColor, theme.colors) },
  ];
  const containerStyles: Style[] = [styles.container];
  if (style) {
    containerStyles.push(style);
  }

  return (
    <View wrap={!noWrap} style={containerStyles}>
      {rows.map((row, rowIndex) => (
        <View
          key={rowIndex}
          wrap={false}
          style={
            rowIndex === rows.length - 1
              ? styles.row
              : [styles.row, styles.rowGap]
          }
        >
          {row.map((item, index) => (
            <View key={index} style={styles.tile}>
              <PDFText style={styles.label}>{item.label}</PDFText>
              <PDFText style={valueStyle}>{item.value}</PDFText>
              {item.note ? (
                <PDFText style={noteStyle}>{item.note}</PDFText>
              ) : null}
            </View>
          ))}
          {Array.from({ length: columns - row.length }, (_, index) => (
            <View key={`spacer-${index}`} style={styles.spacer} />
          ))}
        </View>
      ))}
    </View>
  );
};

import type { Style } from "@/lib/pdf-primitives";

/** Number of tiles rendered per row. */
export type StatsColumns = 2 | 3 | 4;

/**
 * A single metric tile with a label, a headline value and an optional note.
 * Props - `label` | `value` | `note`
 * @see {@link StatItem}
 */
export interface StatItem {
  label: string;
  value: string;
  note?: string;
}

/**
 * Row of KPI metric tiles for reports and proposals.
 * Props - `items` | `columns` | `accentColor` | `noWrap` | `style`
 * @see {@link StatsProps}
 */
export interface StatsProps {
  items: StatItem[];
  /**
   * Tiles per row. Extra items wrap onto a new row with the same tile width.
   * @default 3
   */
  columns?: StatsColumns;
  /**
   * Theme color token or CSS color used for the note line.
   * @default 'primary'
   */
  accentColor?: string;
  /**
   * @default false
   */
  noWrap?: boolean;
  style?: Style;
}
